-- Real data for Nairobi City County, researched from public reporting and official documents (October 2026).
-- Every row names its source and links to it. Statuses describe what the cited reporting shows, not opinion.
-- Load into a Nairobi project only. Safe to run again: existing rows are updated by slug or by county and year.

-- Governor's promises (promise tracker)
insert into public.commitments (slug, title, title_sw, detail, source, source_url, made_on, due_on, sector, status, evidence) values
  ('school-feeding-dishi-na-county', 'Feed children in every public primary school (Dishi na County)', 'Kulisha watoto katika kila shule ya msingi ya umma (Dishi na County)', 'Campaign promise of free lunch in all public schools to raise transition from one level to the next. Delivered as Dishi na County: meals at a subsidised Sh5 for primary learners.', 'Campaign manifesto 2022 (12 mega projects)', 'https://www.kenyans.co.ke/news/78890-12-mega-projects-sakaja-promised-nairobi-residents', null, null, 'Education', 'in_progress', 'Reported in October 2025 to feed about 316,000 learners a day in more than 230 public primary schools and ECDE centres from 17 central kitchens. The county cabinet gave the programme legal backing in February 2026. Extending it to informal schools awaits funding. Sources: the-star.co.ke 2025-10-30, the-star.co.ke 2026-02-06.'),
  ('twenty-modern-markets', 'Build 20 new modern markets', 'Kujenga masoko mapya 20 ya kisasa', 'Promised in the 2022 campaign to decongest the main city markets. In August 2024 the governor restated the target as 20 markets by 2027.', 'Campaign rally, July 2022; restated August 2024', 'https://www.capitalfm.co.ke/news/2024/08/sakaja-pledges-20-modern-markets-in-nairobi-by-2027-to-boost-trade/', '2022-07-20', null, 'Trade', 'in_progress', 'Reported complete: Mwariro, Westlands, Karandini, Gikomba and Kangundo Road markets. Under construction include Mutuini and Kahawa West. The Auditor-General reported that Sh69.5 million was spent on Mutuini market while the project stalled. Its 2024/25 report lists contracts for Kahawa West market (re-tendered, Sh156,899,199) and Karen market (Sh235,369,272), with tax and retention deductions not remitted. Sources: eastleighvoice.co.ke (Auditor-General on Mutuini), nairobi.go.ke, Auditor-General County Executives 2024/25 paragraph 1317.9.'),
  ('ward-biashara-fund', 'Sh50 million biashara fund every year for each of the 85 wards', 'Mfuko wa biashara wa Sh50 milioni kila mwaka kwa kila wadi kati ya 85', 'Campaign promise to fund small businesses in every ward. At Sh50 million for 85 wards this is about Sh4.25 billion a year.', 'Campaign, July 2022', 'https://www.the-star.co.ke/counties/nairobi/2022-07-28-igathe-sakaja-promise-better-services-for-nairobians-if-elected/', '2022-07-28', null, 'Trade', 'delayed', 'Implemented at a much smaller scale: in 2023 the county set aside Sh100 million in total for a revolving Biashara Fund for women, youth and people with disabilities across all wards. A Biashara Stimulus Programme was announced in November 2025 without a start date or amount. Sources: the-star.co.ke 2023-07-05, the-star.co.ke 2025-11-14.'),
  ('metro-commuter-rail', 'Build a city metro commuter rail to decongest the CBD', 'Kujenga reli ya abiria ya jiji ili kupunguza msongamano katikati ya jiji', 'Campaign and inauguration promise of a metro commuter light rail.', 'Inauguration, 25 August 2022', 'https://nairobinews.nation.africa/10-promises-governor-sakaja-made-to-nairobians/', '2022-08-25', null, 'Transport', 'in_progress', 'Planning stage only, no construction. The county cabinet approved phase 1 of the Nairobi Metropolitan Mass Rapid Transit System: a 30 km underground line from Eastlands to the CBD with 25 stations. The President endorsed it; financing is still being worked out and a project management unit is being set up. The whole programme is estimated at USD 7.78 billion. Sources: the-star.co.ke 2026-09-04, railjournal.com.'),
  ('boroughs-decentralise', 'Divide Nairobi into boroughs run by city managers to bring services closer', 'Kugawa Nairobi katika boroughs zinazoongozwa na mameneja ili kuleta huduma karibu', 'Campaign promise of five boroughs. A taskforce later recommended six: Central, Eastern, Western, Northern, Southern and South Eastern.', 'Campaign 2022; inauguration', 'https://www.the-star.co.ke/counties/nairobi/2023-05-28-sakajas-plan-to-subdivide-city-decentralise-services', '2022-08-25', null, 'Governance', 'in_progress', 'Six borough managers were appointed in November 2025 and met the governor for the first time on 4 December 2025. Each borough is meant to have one plan and one budget. Sources: the-star.co.ke 2025-11-18, the-star.co.ke 2025-12-04.'),
  ('clean-city-garbage', 'Keep Nairobi clean: fix garbage collection, e-waste and sewage', 'Kuweka Nairobi safi: ukusanyaji taka, taka za kielektroniki na maji taka', 'Inauguration promise of an e-waste handling system and sewerage works so sewage stops polluting streets.', 'Inauguration, 25 August 2022', 'https://nairobinews.nation.africa/10-promises-governor-sakaja-made-to-nairobians/', '2022-08-25', null, 'Environment', 'delayed', '24 new refuse trucks were flagged off and about 3,500 young people work as the Green Army. A county company, Green Nairobi, was created; its board was gazetted on 14 August 2026. In a podcast released on 2 September 2026 the governor himself named garbage among promises that have not been delivered. In October 2026 the county reported about 4,500 Green Army workers and said it collects about 3,200 tonnes of garbage a day (the county''s own figures). Sources: peopledaily.digital, citizen.digital, capitalfm.africa (October 2026).'),
  ('dandora-waste-to-energy', 'Turn Dandora dumpsite waste into 45 MW of electricity', 'Kubadilisha taka za Dandora kuwa umeme wa megawati 45', 'A project development agreement was signed with China National Electric Engineering Company on 19 September 2025. The power purchase agreement was still being finalised by the Ministry of Energy and EPRA.', 'Project agreement signing, 19 September 2025', 'https://businesstoday.co.ke/sakaja-seals-45mw-dandora-energy-deal/', '2025-09-19', null, 'Environment', 'delayed', 'In a podcast released on 2 September 2026 the governor named the Dandora waste-to-energy project as the promise that has not moved as planned. Source: peopledaily.digital.'),
  ('end-water-shortage-2026', 'End water shortages in Nairobi by 2026', 'Kumaliza uhaba wa maji Nairobi kufikia 2026', 'The governor said perennial water shortages would be history by 2026, mainly through the Northern Collector Tunnel.', 'Statement, 1 October 2023', 'https://www.the-star.co.ke/news/realtime/2023-10-01-nairobis-water-shortage-will-be-history-by-2026-sakaja', '2023-10-01', '2026-12-31', 'Water', 'in_progress', 'The Northern Collector Tunnel is complete and adds about 140 million litres a day. Reported demand is about 900 million litres a day against supply of about 525 million before the tunnel, so a gap remains. A second tunnel and the Maragua project are expected by 2027. Sources: citizen.digital, nation.africa.'),
  ('vocational-training-centres', 'Build and equip vocational training centres as skills hubs', 'Kujenga na kuandaa vyuo vya ufundi kama vituo vya ujuzi', 'Campaign promise to turn the county vocational training centres into technical and skills hubs.', 'Campaign, July 2022', 'https://www.the-star.co.ke/counties/nairobi/2022-07-28-igathe-sakaja-promise-better-services-for-nairobians-if-elected/', '2022-07-28', null, 'Education', 'in_progress', 'We found no public report of new centres completed. In September 2025 the Senate Education Committee summoned the governor over the state of ECDE and vocational centres after he cancelled an appearance. Source: capitalfm.co.ke 2025-09.'),
  ('county-blood-bank', 'Set up a county blood bank', 'Kuanzisha benki ya damu ya kaunti', 'Part of the 2022 health plan among the 12 mega projects.', 'Campaign manifesto 2022 (12 mega projects)', 'https://www.kenyans.co.ke/news/78890-12-mega-projects-sakaja-promised-nairobi-residents', null, null, 'Health', 'not_started', 'We found no public report that a county blood bank has been set up. Critics listed it among unmet promises in December 2025. Source: peopledaily.digital.'),
  ('single-business-permit', 'One electronic business permit instead of many licences', 'Kibali kimoja cha kielektroniki cha biashara badala ya leseni nyingi', 'Campaign promise to cut the number of licences, reduce corruption and raise revenue.', 'Campaign manifesto 2022 (12 mega projects)', 'https://www.kenyans.co.ke/news/78890-12-mega-projects-sakaja-promised-nairobi-residents', null, null, 'Trade', 'delivered', 'The Unified Business Permit started on 1 January 2024. It combines the business permit, fire, food hygiene, pest control, health and advertising licences, and is paid on NairobiPay (*647#). Source: the-star.co.ke 2024-01-01.'),
  ('ecde-classrooms-1500', 'Build 1,500 ECDE classrooms', 'Kujenga madarasa 1,500 ya ECDE', 'Restated by the governor as enrolment rose with school feeding. The national government is separately building about 5,000 classrooms in Nairobi.', 'Governor statement reported by Citizen Digital', 'https://citizen.digital/news/nairobi-governor-sakaja-reaffirms-commitment-to-ecde-classrooms-and-childcare-reforms-n349762', null, null, 'Education', 'in_progress', 'Construction reported as ongoing; we found no published count of classrooms finished. Source: citizen.digital.'),
  ('ward-funds-on-time', 'Pay ward development funds on time to all 85 wards', 'Kulipa fedha za maendeleo za wadi kwa wakati kwa wadi zote 85', 'Promised in the maiden address to the County Assembly on 19 October 2022.', 'Maiden address to the County Assembly, 19 October 2022', 'https://www.the-star.co.ke/counties/nairobi/2022-10-19-this-is-my-plan-for-nairobi-sakaja-says-in-maiden-assembly-speech/', '2022-10-19', null, 'Governance', 'in_progress', 'The allocation rose from Sh1.4 billion to Sh2 billion in 2023/24, but the governor told the Senate the county disbursed Sh715 million in 2022/23, Sh925 million in 2023/24 and Sh889 million in 2024/25. Sources: nairobi.go.ke, eastleighvoice.co.ke.'),
  ('sports-complex-every-subcounty', 'A modern sports complex in each of the 17 sub-counties', 'Uwanja wa kisasa wa michezo katika kila kaunti ndogo kati ya 17', 'Promise to build a sports facility in every sub-county.', 'Governor statement', 'https://www.mozzartsport.co.ke/football/news/governor-sakaja-promises-sophisticated-sports-complex-in-every-nairobi-sub-county/20399', null, null, 'Sports', 'in_progress', 'Dandora Stadium opened after a six-year delay at a cost of more than Sh276 million, and the Uhuru Complex sports arena opened in March 2024. Kihumbuini Stadium was reported more than 70 percent complete; Woodley and City Stadium are being upgraded. Sources: nairobi.go.ke, the-star.co.ke 2024-03-23, tv47.digital.'),
  ('affordable-housing-40000', '40,000 affordable homes through urban renewal of county estates', 'Nyumba 40,000 za bei nafuu kupitia ukarabati wa mitaa ya kaunti', 'Plan to redevelop old county estates, 70 percent of units affordable at Sh1.5 million to Sh3.5 million. Nine estates earmarked: Bahati, Maringo, Jericho, Lumumba, Ziwani, Bondeni, Kariobangi, Embakasi and Woodley.', 'Plan announced March 2023', 'https://www.the-star.co.ke/counties/nairobi/2023-03-08-how-sakaja-plans-to-set-up-40000-affordable-housing-units/', '2023-03-08', null, 'Housing', 'in_progress', 'The Jeevanjee and Bachelors project in Ngara reached 1,800 units, with phase one expected by August 2025. MCAs have called for a probe into stalled housing projects. The Auditor-General found the Pangani affordable housing project (1,562 units, begun in early 2020) stalled for reasons not explained, with no county action on the owners'' complaint of 23 October 2024. Sources: the-star.co.ke 2025-05-30, eastleighvoice.co.ke, Auditor-General County Executives 2024/25 paragraph 1317.11.'),
  ('land-titling-2025', 'Complete land titling in Nairobi by 2025', 'Kukamilisha utoaji hati miliki za ardhi Nairobi kufikia 2025', 'Made while issuing 912 title deeds.', 'Title deed issuance event', 'https://eastleighvoice.co.ke/city-affairs/76645/sakaja-issues-912-title-deeds-vows-to-complete-nairobi-land-titling-by-2025', null, '2025-12-31', 'Lands', 'in_progress', '1,000 more title deeds were issued in September 2024. We found no report that titling was completed by the end of 2025. Source: the-star.co.ke 2024-09-19.'),
  ('ruto-sakaja-80bn-pact', 'Sh80 billion national and county cooperation agreement for roads, water, power, sanitation and waste', 'Makubaliano ya ushirikiano ya Sh80 bilioni kwa barabara, maji, umeme, usafi na taka', 'Signed by President Ruto and Governor Sakaja on 17 February 2026.', 'Cooperation agreement, 17 February 2026', 'https://www.the-star.co.ke/news/2026-02-17-ruto-sakajas-shh80bn-deal-to-transform-nairobi', '2026-02-17', null, 'Infrastructure', 'in_progress', 'The Senate recommended suspending the agreement over governance concerns, and an Assembly committee asked for a full list of projects within 30 days. A court challenge was filed. Sources: nairobilawmonthly.com, eastleighvoice.co.ke, nation.africa.'),
  ('el-nino-flood-plan-2026', 'Clear rivers and drains before the El Nino rains (six-point flood plan)', 'Kusafisha mito na mitaro kabla ya mvua za El Nino (mpango wa hatua sita)', 'Announced on 8 October 2026: restore the capacity of the Nairobi, Ngong and Mathare rivers by desilting and dredging, move residents out of danger zones voluntarily, deploy the Green Army on drains and waste, and mobilise communities through the six boroughs.', 'Six-point El Nino plan, 8 October 2026', 'https://www.the-star.co.ke/news/2026-10-08-sakaja-unveils-six-point-plan-to-tackle-el-nino-floods-in-nairobi', '2026-10-08', null, 'Environment', 'in_progress', 'About 4,500 Green Army workers were deployed to clear drains and waste. On 12 October the county said 80 percent of river clearance on the Nairobi, Mathare and Ngong rivers was done and presented a Sh10 billion flood programme to the national implementation committee; both figures are the county''s own, and no budget breakdown has been published. Sources: the-star.co.ke 2026-10-08, capitalfm.africa, thekenyatimes.com.')
on conflict (slug) do update set title = excluded.title, title_sw = excluded.title_sw, detail = excluded.detail, source = excluded.source,
  source_url = excluded.source_url, made_on = excluded.made_on, due_on = excluded.due_on, sector = excluded.sector,
  status = excluded.status, evidence = excluded.evidence;

-- County finance is in supabase/data/kenya_county_finance.sql (all 47 counties, from the Controller of Budget and
-- Auditor-General reports). Load that file after this one.

-- County projects with published costs. "spent" is only filled where a figure was published; zero means not published
-- (the site says so). Each description names its sources.
insert into public.projects (slug, ward_id, title, sector, description, status, budget, spent, started_at, expected_at, completed_at, published) values
  ('dandora-stadium', 'dandora-area-iv', 'Dandora Stadium', 'Sports',
   'Sub-county stadium completed after a six-year delay and opened in March 2024, built at a cost of more than Sh276 million (figure as reported). Sources: the-star.co.ke 2024-03-08; nairobi.go.ke.',
   'completed', 276000000, 276000000, null, null, '2024-03-08', true),
  ('kihumbuini-stadium', 'kangemi', 'Kihumbuini Stadium redevelopment', 'Sports',
   'A 5,000-seat stadium for Kangemi, Kawangware and Westlands, launched on 20 June 2024 at an estimated Sh277 million with an 18-month build. Reported more than 70 percent complete in August 2026. The county treasury reported Sh179,863,452 spent on it in 2025/26, one of its ten largest development payments that year. Sources: the-star.co.ke 2024-06-20; standardmedia.co.ke 2026-08; Controller of Budget 2025/26, Table 3.465.',
   'in_progress', 277000000, 179863452, '2024-06-20', '2025-12-20', null, true),
  ('mutuini-market', 'mutuini', 'Mutuini market', 'Markets',
   'The first of the 20 promised markets. Contract of Sh242 million awarded on 7 February 2024 for completion by 7 August 2024. The Auditor-General found Sh69.5 million paid and the project stalled, with no status report, in October 2024. Source: eastleighvoice.co.ke (Auditor-General report).',
   'stalled', 242000000, 69500000, '2024-02-07', '2024-08-07', null, true),
  ('woodley-stadium', 'woodley-kenyatta-golf-course', 'Woodley Stadium upgrade', 'Sports',
   'The first contractor, awarded Sh135,245,229 in 2022/23, was paid Sh29,885,152 and left the site about 20 percent done. A new contract of Sh123,957,878 was awarded on 2 August 2024 for terraces, a playground and a toilet block, without the unfinished earlier works. Spending on the new contract has not been published. Source: Auditor-General, County Executives 2023/24, Nairobi City, paragraph 1044.6.',
   'in_progress', 123957878, 0, '2024-08-02', null, null, true),
  ('governors-residence-lady-northey', 'kilimani', 'Governor''s official residence, Lady Northey', 'County buildings',
   'Contract of Sh235,323,395, to be finished 40 weeks after site possession on 22 April 2024. By 30 June 2025 two payment certificates totalling Sh89,470,154 had been paid, Sh145,853,241 of the contract was not yet certified and the work was unfinished, although the completion period ran out by 24 February 2025. The Auditor-General noted that the contract far exceeds the Sh45,000,000 ceiling in the Salaries and Remuneration Commission guidelines for governors'' residences, that Sh17,000,000 was paid without supporting documents, and that ownership of the site could not be verified. The press reports the residence is being built in Kilimani. Sources: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1317.2; peopledaily.digital.',
   'in_progress', 235323395, 89470154, '2024-04-22', '2025-02-24', null, true),
  ('gikomba-fire-station', 'pumwani', 'Gikomba Market fire station', 'Safety',
   'Contract of Sh59,983,162. A payment certificate of Sh30,024,578, half the contract sum, was paid by 28 June 2024. When the Auditor-General inspected on 30 July 2025, materials that had been paid for were not on site, the contractor was absent and the works were incomplete, with substandard staircases, the water tank taken down and drainage unfinished; part of the land had been taken up by the market. Only 3 percent retention (Sh900,737) was held instead of 10 percent (Sh2,999,158), so the contractor was overpaid by Sh2,098,421. Shown as stalled because the contractor was absent and the works incomplete at that inspection. Source: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1313.18.',
   'stalled', 59983162, 30024578, null, null, null, true),
  ('shiranga-hospital-wall', 'njiru', 'Shiranga Hospital perimeter wall, guard house and gates', 'Health',
   'Tender of Sh11,599,315 for six months from 2 September 2024. The Auditor-General found the evaluation committee''s minutes dated 21 February 2024, before the tender closed on 1 March 2024, and the contract signed on 2 July 2024, 90 days after the tender notification of 2 April 2024 and beyond its validity. The bill of quantities, site instructions, invoices and project file were missing, and Sh583,870 of retention was not deposited in the county deposit account. The report does not say whether the works were finished or how much was paid. Source: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1317.3.',
   'in_progress', 11599315, 0, '2024-09-02', '2025-03-02', null, true),
  ('parklands-cancer-diagnostic-centre', 'parklands-highridge', 'Cancer Diagnostic Centre, Parklands sub-county offices', 'Health',
   'Contract of Sh39,998,609 for six months from 2 October 2023. The Auditor-General found that the professional opinion covered four bidders while the evaluation minutes showed one, and was dated 19 June 2023, three days after the evaluation. The approved bill of quantities, site instructions, project file and status report were missing, and Sh3,388,108 of retention was not deposited in the county deposit account. The report does not say whether the centre was finished or how much was paid. Source: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1317.4.',
   'in_progress', 39998609, 0, '2023-10-02', '2024-04-02', null, true),
  ('nyangusi-road-umoja', 'umoja-i', 'Nyangusi Road, Umoja I', 'Roads',
   'Contract of Sh19,700,094 for six months from 18 April 2024. The Auditor-General found no advertisement and a single bidder, in effect a direct award without the required justification; the purchase order was dated 14 November 2024, after the works had started; no laboratory test certificates, road designs, bills of quantities or site reports were on file; and Sh1,967,043 retained from the first payment certificate was not transferred to the county deposit account. The report does not say whether the road was finished or how much was paid. Source: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1317.6.',
   'in_progress', 19700094, 0, '2024-04-18', '2024-10-18', null, true),
  ('karen-market', 'karen', 'Karen market', 'Markets',
   'Contract of Sh235,369,272. The Auditor-General found that withholding VAT of Sh1,042,140, withholding income tax of Sh1,813,324 and retention of Sh6,044,415 were not remitted although the contractor had been paid. The report does not give the start date, the amount paid or whether the market was finished. Source: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1317.9.',
   'in_progress', 235369272, 0, null, null, null, true),
  ('kahawa-west-market', 'kahawa-west', 'Kahawa West market', 'Markets',
   'Re-tendered and awarded at Sh156,899,199. The Auditor-General found deductions of Sh6,545,542 not remitted, and the performance security expired shortly after the contractual completion date. The county lists Kahawa West among the markets under construction. The county treasury reported Sh70,795,422 spent on the market in 2025/26, one of its ten largest development payments that year. Sources: Auditor-General, County Executives 2024/25, Nairobi City, paragraph 1317.9; nairobi.go.ke; Controller of Budget 2025/26, Table 3.465.',
   'in_progress', 156899199, 70795422, null, null, null, true)
on conflict (slug) do update set ward_id = excluded.ward_id, title = excluded.title, sector = excluded.sector, description = excluded.description,
  status = excluded.status, budget = excluded.budget, spent = excluded.spent, started_at = excluded.started_at, expected_at = excluded.expected_at,
  completed_at = excluded.completed_at, published = true;

-- Stalled projects as the county treasury reported them at 30 June 2026 (Controller of Budget, County Governments
-- Budget Implementation Review Report 2025/26, Table 3.466: 57 projects, Sh2.24 billion, Sh208.88 million paid).
-- 48 are here. Left out because the ward cannot be told from the table: rows 8 (constituency only), 24 (Kayole 1),
-- 25 (Dandora, no ward number), 44 and 51 (sub-county offices); row 22 (Tasia kwa Ndege) because Table 3.465 gives a
-- different figure for it; row 34 (no value), row 41 (no name) and row 56 (a van). Wards come from the table's location
-- column; Runda, Uhuru Park, Jeevanjee Gardens and the ASK Showground were placed on the ward map. A paid amount of
-- zero means none is listed.
insert into public.projects (slug, ward_id, title, sector, description, status, budget, spent, started_at, expected_at, completed_at, published) values
  ('icrms-erp-system', 'nairobi-central', 'ICRMS/ERP system, City Hall', 'ICT',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh847,229,897. Paid so far: Sh150,000,000. Reported 37 percent complete. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 1).',
   'stalled', 847229897, 150000000, null, null, null, true),
  ('mbagathi-medical-block', 'woodley-kenyatta-golf-course', 'Mbagathi Hospital medical block (outpatients, HDU and ICU)', 'Health',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh255,870,376. No payment is listed. Reported 15 percent complete. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 2).',
   'stalled', 255870376, 0, null, null, null, true),
  ('mwiki-social-hall', 'mwiki', 'Mwiki social hall', 'Social',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh76,000,000. No payment is listed. The county''s note: contractor not on site due to non-payment. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 3).',
   'stalled', 76000000, 0, null, null, null, true),
  ('dandora-ii-youth-complex', 'dandora-area-ii', 'Dandora II youth complex', 'Social',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh50,000,000. No payment is listed. The county''s note: contractor not on site due to non-payment. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 4).',
   'stalled', 50000000, 0, null, null, null, true),
  ('huruma-flats-perimeter-wall', 'huruma', 'Perimeter wall, Huruma Flats', 'Housing',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh42,865,608. No payment is listed. Reported 10 percent complete. The county''s note: contractor not on site. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 5).',
   'stalled', 42865608, 0, null, null, null, true),
  ('makina-market-rehabilitation', 'makina', 'Makina market rehabilitation', 'Markets',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh42,000,000. No payment is listed. Reported 10 percent complete. The county''s note: project stalled due to non-payment. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 6).',
   'stalled', 42000000, 0, null, null, null, true),
  ('jeevanjee-gardens-revitalisation', 'nairobi-central', 'Jeevanjee Gardens revitalisation (completion works)', 'Environment',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh37,896,320. No payment is listed. Reported 51 percent complete. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 7).',
   'stalled', 37896320, 0, null, null, null, true),
  ('ask-showground-incubation-hub', 'woodley-kenyatta-golf-course', 'Incubation hub centre, ASK Showground', 'Trade',
   'Listed by the county treasury among 57 stalled projects at 30 June 2026. Estimated value Sh34,000,000. No payment is listed. Reported 30 percent complete. The county''s note: non-payment of the 1st certificate. Source: Controller of Budget, County Governments Budget Implementation Review Report 2025/26, Table 3.466 (row 9).',
   'stalled', 34000000, 0, null, null, null, true),
  ('cbd-hawkers-sheds', 'nairobi-central', 'Hawkers sheds in 10 lanes', 'Markets',
